// Pick up leads that still need data.
//
// Terminal states are skipped so failed leads are not retried nightly
// forever (that was what blew the Sheets quota).
//
// pattern_unknown / pattern_inferred are RETRYABLE: the address pattern is
// unproven, but a verified peer at the same domain may appear later and
// upgrade them.
const TERMINAL  = new Set(['enriched', 'needs_manual_review', 'domain_not_found']);
const RETRYABLE = new Set(['pattern_unknown', 'pattern_inferred']);

const out = [];

for (const item of items) {
  const d = item.json || {};
  const status = String(d.enriched_status || '').trim();
  const src    = String(d.email_source || '').trim();

  // --- Legacy migration -------------------------------------------------
  // Rows written before the pattern resolver existed were marked 'enriched'
  // with a bare 'pattern_guess' source, but the address was always assumed
  // to be first.last@ with no evidence behind it. Re-admit them once so the
  // evidence-based resolver can replace them.
  //
  // Self-clearing: after reprocessing they take a qualified source such as
  // 'domain_peer:first.last' or 'pattern_guess:unevidenced', so they will
  // not match this rule again.
  if (status === 'enriched' && src === 'pattern_guess') {
    out.push({ json: d });
    continue;
  }
  // ----------------------------------------------------------------------

  if (TERMINAL.has(status)) continue;

  if (RETRYABLE.has(status)) {
    out.push({ json: d });
    continue;
  }

  // Never processed before
  if (status === '' && (!d.company_domain || !d.email)) {
    out.push({ json: d });
  }
}

return out;

const headline = $json.headline || '';
let companyName = null;

// Handles: "Title at Company", "Title @ Company", "Title | Company"
const atMatch = headline.match(/\bat\s+(.+?)(?:\s*[|\-\u2013]|$)/i);
const atSymbolMatch = headline.match(/@\s*(.+?)(?:\s*[|\-\u2013]|$)/);
const pipeMatch = headline.match(/\|\s*(.+?)$/);

if (atMatch) companyName = atMatch[1].trim();
else if (atSymbolMatch) companyName = atSymbolMatch[1].trim();
else if (pipeMatch) companyName = pipeMatch[1].trim();

// Strip noise so the domain guess isn't polluted
if (companyName) {
  companyName = companyName
    .replace(/\(.*?\)/g, '')
    .replace(/[\u2122\u00ae\u00a9]/g, '')
    .split(/,| and | & | \| /i)[0]
    .replace(/^@/, '')
    .replace(/\s+/g, ' ')
    .trim();

  const words = companyName.split(/\s+/).filter(Boolean);
  const junk = /^(company|non-?profit development|business development|program management|consultant|freelance)$/i;
  if (words.length > 5 || junk.test(companyName) || companyName.length < 2) {
    companyName = null;
  }
}

return {
  json: {
    ...$json,
    company_name: companyName,
    company_name_source: companyName ? 'headline_parsed' : null
  }
};

const companyName = $json.company_name;
if (!companyName) return { json: { ...$json, domain_candidates: [] } };

const cleaned = companyName
  .replace(/\b(inc|llc|corp|corporation|foundation|nonprofit|non-profit|ltd|co)\.?\b/gi, '')
  .replace(/[^\w\s]/g, '')
  .trim();

const words = cleaned.toLowerCase().split(/\s+/).filter(Boolean);

// Generic role/sector words. Guessing a domain from these lands on squatted
// domains that pass an MX check but belong to someone else entirely
// (e.g. "Nonprofit Leader" -> leader.com -> anne.friedman@leader.com).
const GENERIC = new Set([
  'leader','leaders','leadership','consultant','consultants','consulting','consultancy',
  'advisor','advisors','advisory','services','service','solutions','group','partners',
  'partner','associates','agency','ventures','capital','holdings','global','international',
  'national','regional','local','community','communities','network','networks','institute',
  'society','association','alliance','coalition','council','center','centre','initiative',
  'project','projects','program','programs','programme','development','strategy','strategies',
  'strategic','management','marketing','media','digital','creative','director','executive',
  'founder','cofounder','owner','president','chair','chairman','manager','officer','principal',
  'entrepreneur','freelance','freelancer','independent','self','employed','retired','various',
  'multiple','company','business','businesses','enterprise','enterprises','charity','charities',
  'philanthropy','philanthropic','fundraising','fundraiser','grants','grant','funding','funds',
  'impact','change','future','health','healthcare','education','technology','tech','innovation',
  'research','training','coaching','team','office','department','division','board','trust',
  'the','and','for','with','group of','llc'
]);

const allGeneric = words.length > 0 && words.every(w => GENERIC.has(w));
if (words.length === 0 || allGeneric) {
  return {
    json: {
      ...$json,
      domain_candidates: [],
      domain_rejected_reason: 'generic_company_name'
    }
  };
}

// A lone short or generic token is too weak to guess from
if (words.length === 1 && (GENERIC.has(words[0]) || words[0].length < 4)) {
  return {
    json: {
      ...$json,
      domain_candidates: [],
      domain_rejected_reason: 'company_name_too_weak'
    }
  };
}

const noSpaces = cleaned.replace(/\s+/g, '').toLowerCase();
const withDashes = cleaned.split(/\s+/).join('-').toLowerCase();
const firstWord = words[0] || '';
const firstTwo = words.slice(0, 2).join('') || firstWord;

// Full-name forms first: "yougottabelieve.org" is far more likely to be the
// real org than the truncated "yougotta.com". .org before .com for nonprofits.
const raw = [
  `${noSpaces}.org`,
  `${noSpaces}.com`,
  `${withDashes}.org`,
  `${withDashes}.com`,
  `${firstTwo}.org`,
  `${firstTwo}.com`,
  `${firstWord}.org`,
  `${firstWord}.com`
];

const candidates = [...new Set(raw)].filter(d => {
  if (d.length <= 8) return false;              // drop ".com" / tiny stubs
  const label = d.replace(/\.(com|org)$/, '');
  if (GENERIC.has(label)) return false;         // never guess a bare generic word
  if (label.length < 4) return false;
  return true;
});

return { json: { ...$json, domain_candidates: candidates } };

const candidates = $json.domain_candidates || [];
let verifiedDomain = null;

for (const domain of candidates) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://dns.google/resolve?name=${domain}&type=MX`,
      json: true
    });
    if (data.Answer && data.Answer.length > 0) {
      verifiedDomain = domain;
      break;
    }
  } catch (e) {}
}

const result = {
  ...$json,
  company_domain: verifiedDomain || '',
  domain_verified: !!verifiedDomain
};

return { json: result };

// Apply the pattern resolved upstream. Only emit a sendable address
// when the pattern is evidenced; otherwise flag pattern_unknown and
// let LinkedIn outreach handle the lead.
const out = Object.assign({}, $json);

const domain = String(out.company_domain || '').trim().toLowerCase();
const first = String(out.name_first || '').trim().toLowerCase();
const last = String(out.name_last || '').trim().toLowerCase();

if (!domain || !first || !last) {
  out.email = '';
  out.email_candidates = [];
  out.enrichment_status = out.enrichment_status || 'needs_manual_review';
  return { json: out };
}

const PATTERNS = {
  'first.last': (f, l) => f + '.' + l,
  'first':      (f, l) => f,
  'flast':      (f, l) => f[0] + l,
  'firstlast':  (f, l) => f + l,
  'first_last': (f, l) => f + '_' + l,
  'f.last':     (f, l) => f[0] + '.' + l,
  'last.first': (f, l) => l + '.' + f,
  'firstl':     (f, l) => f + l[0],
  'lastf':      (f, l) => l + f[0]
};

// Ranked fallbacks, kept for reference only - never auto-selected
const ORDER = ['first.last','first','flast','firstlast','f.last','first_last','last.first'];
out.email_candidates = ORDER.map(k => PATTERNS[k](first, last) + '@' + domain);

const pattern = String(out.email_pattern || '');
const src = String(out.email_pattern_source || 'unknown');

if (pattern && PATTERNS[pattern]) {
  out.email = PATTERNS[pattern](first, last) + '@' + domain;
  out.email_source = src + ':' + pattern;
  out.email_verified = (src === 'domain_peer');

  // domain_peer  -> reverse-engineered from a real name+address pair. Exact.
  // site_scrape  -> shape inferred from an address whose owner is unknown.
  //                 'first' vs 'flast' is genuinely ambiguous at this stage,
  //                 so keep it upgradeable rather than marking it terminal.
  out.enrichment_status = (src === 'domain_peer') ? 'enriched' : 'pattern_inferred';
} else {
  // No evidence for this domain. Keep the most likely guess visible in the
  // sheet so it can be upgraded later, but do NOT mark it sendable.
  out.email = PATTERNS['first.last'](first, last) + '@' + domain;
  out.email_source = 'pattern_guess:unevidenced';
  out.email_verified = false;
  out.enrichment_status = 'pattern_unknown';
}

return { json: out };

// Confidence now reflects real evidence. Previously smtp_verified and
// profile_lookup were never set by any node, so every lead scored 40.
const out = Object.assign({}, $json);

const patternSrc = String(out.email_pattern_source || 'unknown');
const domainSrc = String(out.company_domain_source || '');

let score = 0;

// Domain evidence
if (out.domain_verified === true) score += 20;
if (domainSrc === 'serpapi_fallback') score += 5;   // corroborated by search + MX

// Company name evidence
if (out.company_name_source === 'profile_lookup') score += 15;
else if (out.company_name_source === 'headline_parsed') score += 5;

// Address pattern evidence - the part that actually decides deliverability
if (patternSrc === 'domain_peer') score += 50;      // reverse-engineered from a real address
else if (patternSrc === 'site_scrape') score += 30; // shape inferred from a scraped address

if (score > 100) score = 100;

out.email_confidence = score;
out.enrichment_status = out.enrichment_status || 'enriched';
out.enriched_at = new Date().toISOString();

// Explicit send gate so downstream outreach never has to re-derive this
out.email_sendable = (out.enrichment_status === 'enriched' && score >= 70);

