  'company_name','company_name_source','company_domain','email','email_source',
  'email_confidence','email_verified','enriched_at'
];

const clean = {};
for (const f of LEAD_FIELDS) {
  clean[f] = lead[f] !== undefined ? lead[f] : '';
}

// ---- 6. Apply the domain result ----
clean._debug_serp_source = serpSource;
clean._debug_results_count = Array.isArray(serp.organic_results) ? serp.organic_results.length : -1;
clean._debug_candidates = serpCandidates.map(([l]) => l).join(',');
clean._debug_first_link = (serp.organic_results && serp.organic_results[0]) ? serp.organic_results[0].link : 'NONE';

// ---- 6b. FIX: actually apply the domain result to the output ----
clean.company_domain = domain || '';
clean.company_domain_source = domain ? 'serpapi_fallback' : '';
clean.company_domain_mx_ok = mxOk;
clean.domain_verified = !!domain;

return { json: clean };

// ===========================================================
// Resolve Email Pattern
// Works out HOW a domain forms addresses, instead of always
// assuming first.last@ (which was hardcoded as candidates[0]).
//
// FALLBACK: set ENABLE_MAILTO_SCRAPE = false to switch off all
// site fetching. Everything still works from domain peers alone.
// ===========================================================
const ENABLE_MAILTO_SCRAPE = true;
const SCRAPE_TIMEOUT_MS = 4000;   // was 8000 - slow sites were stalling runs
const SCRAPE_MAX_PAGES = 1;      // was 3 - homepage only

const http = (opts) => this.helpers.httpRequest(opts);

// ---------- name handling ----------
const deaccent = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '');
const tidy = (s) => deaccent(s).toLowerCase().replace(/[^a-z\s'-]/g, ' ').replace(/\s+/g, ' ').trim();

const TITLES = new Set(['dr','mr','mrs','ms','miss','prof','professor','rev','fr','sir','dame','hon']);
const SUFFIXES = new Set(['jr','sr','ii','iii','iv','phd','md','mba','cpa','esq','msw','rn','cfre','cae']);

function parseName(raw) {
  let parts = tidy(raw).split(' ').filter(Boolean);
  parts = parts.filter(p => !TITLES.has(p.replace(/[.'-]/g, '')));
  parts = parts.filter(p => !SUFFIXES.has(p.replace(/[.'-]/g, '')));
  parts = parts.filter(p => p.replace(/[^a-z]/g, '').length > 1);
  if (parts.length < 2) return null;
  const first = parts[0].replace(/[^a-z]/g, '');
  const last = parts[parts.length - 1].replace(/[^a-z]/g, '');
  if (!first || !last) return null;
  return { first, last };
}

const PATTERNS = {
  'first.last': (f, l) => f + '.' + l,
  'first':      (f, l) => f,
  'flast':      (f, l) => f[0] + l,
  'firstlast':  (f, l) => f + l,
  'first_last': (f, l) => f + '_' + l,
  'f.last':     (f, l) => f[0] + '.' + l,
  'last.first': (f, l) => l + '.' + f,
  'firstl':     (f, l) => f + l[0],
  'lastf':      (f, l) => l + f[0]
};

function inferPattern(fullName, email) {
  const n = parseName(fullName);
  if (!n) return null;
  const local = String(email || '').split('@')[0].toLowerCase();
  if (!local) return null;
  for (const key of Object.keys(PATTERNS)) {
    try { if (PATTERNS[key](n.first, n.last) === local) return key; } catch (e) {}
  }
  return null;
}

// ---------- 1. Learn patterns from trusted peers already in the pool ----------
const TRUSTED_SOURCES = new Set(['exa_scrape_verified','reply_confirmed','manual','smtp_verified','site_scrape']);
function isTrusted(r) {
  return r.email_verified === true
    || String(r.email_verified).toUpperCase() === 'TRUE'
    || TRUSTED_SOURCES.has(String(r.email_source || ''));
}

let poolRows = [];
try { poolRows = $('Read Lead Pool').all().map(i => i.json); } catch (e) {}

const patternMap = {};
for (const r of poolRows) {
  const em = String(r.email || '').trim().toLowerCase();
  if (!em.includes('@') || !isTrusted(r)) continue;
  const dom = em.split('@')[1];
  if (!dom || patternMap[dom]) continue;
  const p = inferPattern(r.name, em);
  if (p) patternMap[dom] = { pattern: p, evidence: em };
}

// ---------- 2. Shape guess from a scraped address (owner name unknown) ----------
const ROLE = new Set(['info','contact','hello','admin','office','team','hr','support','help','press',
  'media','donate','giving','donations','general','mail','email','enquiries','inquiries','webmaster',
  'noreply','no-reply','sales','marketing','volunteer','events','careers','jobs','communications','post']);

function shapeFromLocal(local) {
  const l = String(local || '').toLowerCase();
  if (!l || ROLE.has(l)) return null;
  if (l.indexOf('_') !== -1) return 'first_last';
  if (l.indexOf('.') !== -1) {
    const bits = l.split('.');
    if (bits.length === 2 && bits[0] && bits[1]) return bits[0].length === 1 ? 'f.last' : 'first.last';
    return null;
  }
  if (/^[a-z]+$/.test(l)) return l.length <= 7 ? 'first' : 'firstlast';
  return null;
}

async function scrapeDomain(domain) {
  const esc = domain.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('[A-Za-z0-9._%+-]+@' + esc, 'gi');
  const urls = ['https://' + domain, 'https://' + domain + '/contact', 'https://' + domain + '/about'];
  for (const u of urls.slice(0, SCRAPE_MAX_PAGES)) {
    try {
      const res = await http({
        method: 'GET', url: u, json: false, timeout: SCRAPE_TIMEOUT_MS,
        headers: { 'User-Agent': 'Mozilla/5.0 (compatible; GFIN-enrichment/1.0)' }
      });
      const text = typeof res === 'string' ? res : JSON.stringify(res);
      const hits = Array.from(new Set((text.match(re) || []).map(x => x.toLowerCase())));
      for (const h of hits) {
        const shape = shapeFromLocal(h.split('@')[0]);
        if (shape) return { pattern: shape, evidence: h };
      }
    } catch (e) {}
  }
  return null;
}

// ---------- 3. Resolve for this lead ----------
const out = Object.assign({}, $json);
const domain = String(out.company_domain || '').trim().toLowerCase();
const person = parseName(out.name);

if (!person) {
  out.email_pattern = '';
  out.email_pattern_source = 'name_not_person';
  out.enrichment_status = 'needs_manual_review';
  return { json: out };
}

out.name_first = person.first;
out.name_last = person.last;

let resolved = (domain && patternMap[domain])
  ? { pattern: patternMap[domain].pattern, evidence: patternMap[domain].evidence, src: 'domain_peer' }
  : null;

if (!resolved && domain && ENABLE_MAILTO_SCRAPE) {
  const scraped = await scrapeDomain(domain);
  if (scraped) resolved = { pattern: scraped.pattern, evidence: scraped.evidence, src: 'site_scrape' };
}

if (resolved) {
  out.email_pattern = resolved.pattern;
  out.email_pattern_source = resolved.src;
  out.email_pattern_evidence = resolved.evidence;
} else {
  out.email_pattern = '';
  out.email_pattern_source = 'unknown';
}

return { json: out };
